<?php
/**
 * Tools > YAPD4Africa import: one-time import of the website's existing
 * content (seed/seed.json, generated by scripts/wp-seed/export.mjs).
 *
 * Runs in small batches with an auto-refreshing progress page, skips any
 * entry whose slug already exists, reuses media already imported, and
 * requests a single website rebuild at the end.
 */

defined( 'ABSPATH' ) || exit;

const YAPD_IMPORT_STATE = 'yapd_import_state';
const YAPD_IMPORT_TIME_BUDGET = 15; // seconds of work per request

/** Seed collection => post type. Order matters: reports link to projects. */
const YAPD_IMPORT_TYPES = array(
	'projects' => 'yapd_project',
	'team'     => 'yapd_team',
	'partners' => 'yapd_partner',
	'reports'  => 'yapd_report',
	'posts'    => 'post',
);

function yapd_import_seed(): array {
	static $seed = null;
	if ( null === $seed ) {
		$file = get_template_directory() . '/seed/seed.json';
		$seed = is_readable( $file ) ? json_decode( (string) file_get_contents( $file ), true ) : array(); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$seed = is_array( $seed ) ? $seed : array();
	}
	return $seed;
}

function yapd_import_find( string $post_type, string $slug ): int {
	$found = get_posts(
		array(
			'post_type'      => $post_type,
			'name'           => $slug,
			'post_status'    => 'any',
			'posts_per_page' => 1,
			'fields'         => 'ids',
			'no_found_rows'  => true,
		)
	);
	return $found ? (int) $found[0] : 0;
}

/** Downloads a file into the media library once; returns its attachment ID. */
function yapd_import_media( ?array $media, int $parent = 0 ): int {
	if ( empty( $media['url'] ) ) {
		return 0;
	}
	$existing = get_posts(
		array(
			'post_type'      => 'attachment',
			'post_status'    => 'inherit',
			'meta_key'       => '_yapd_source', // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
			'meta_value'     => $media['url'], // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_value
			'posts_per_page' => 1,
			'fields'         => 'ids',
		)
	);
	if ( $existing ) {
		return (int) $existing[0];
	}

	require_once ABSPATH . 'wp-admin/includes/file.php';
	require_once ABSPATH . 'wp-admin/includes/media.php';
	require_once ABSPATH . 'wp-admin/includes/image.php';

	$tmp = download_url( $media['url'], 120 );
	if ( is_wp_error( $tmp ) ) {
		throw new RuntimeException( 'Download failed for ' . esc_url_raw( $media['url'] ) . ': ' . $tmp->get_error_message() );
	}
	$id = media_handle_sideload(
		array(
			'name'     => basename( wp_parse_url( $media['url'], PHP_URL_PATH ) ),
			'tmp_name' => $tmp,
		),
		$parent
	);
	if ( is_wp_error( $id ) ) {
		wp_delete_file( $tmp );
		throw new RuntimeException( 'Media import failed: ' . $id->get_error_message() );
	}
	update_post_meta( $id, '_yapd_source', $media['url'] );
	if ( ! empty( $media['alt'] ) ) {
		update_post_meta( $id, '_wp_attachment_image_alt', $media['alt'] );
	}
	return (int) $id;
}

/** Imports one seed entry. Returns 'created' or 'skipped'. */
function yapd_import_entry( string $collection, array $item ): string {
	$post_type = YAPD_IMPORT_TYPES[ $collection ];
	if ( yapd_import_find( $post_type, $item['slug'] ) ) {
		return 'skipped';
	}

	$post = array(
		'post_type'    => $post_type,
		'post_name'    => $item['slug'],
		'post_title'   => $item['title'],
		'post_content' => $item['content'] ?? '',
		'post_excerpt' => $item['excerpt'] ?? '',
		'post_status'  => 'publish',
		'menu_order'   => (int) ( $item['order'] ?? 0 ),
	);
	if ( ! empty( $item['date'] ) ) {
		$post['post_date'] = $item['date'];
	}
	$id = wp_insert_post( wp_slash( $post ), true );
	if ( is_wp_error( $id ) ) {
		throw new RuntimeException( $id->get_error_message() );
	}

	$image = yapd_import_media( $item['image'] ?? null, $id );
	if ( $image ) {
		set_post_thumbnail( $id, $image );
	}
	foreach ( $item['acf'] ?? array() as $name => $value ) {
		update_field( $name, $value, $id );
	}
	if ( 'reports' === $collection ) {
		update_field( 'file', yapd_import_media( $item['file'] ?? null, $id ), $id );
		if ( ! empty( $item['project'] ) ) {
			$project = yapd_import_find( 'yapd_project', $item['project'] );
			if ( $project ) {
				update_field( 'project', $project, $id );
			}
		}
	}
	return 'created';
}

/** Fills empty site settings, keeping every value already entered in WordPress. */
function yapd_import_settings( array $values ): string {
	$current = yapd_get_settings();
	$filled  = $current;
	foreach ( $values as $key => $value ) {
		if ( '' === ( $filled[ $key ] ?? '' ) ) {
			$filled[ $key ] = $value;
		}
	}
	if ( $filled === $current ) {
		return 'skipped';
	}
	update_option( YAPD_OPTION, $filled );
	return 'created';
}

function yapd_import_start(): void {
	$queue = array();
	foreach ( array_keys( YAPD_IMPORT_TYPES ) as $collection ) {
		foreach ( array_keys( yapd_import_seed()[ $collection ] ?? array() ) as $index ) {
			$queue[] = array( $collection, $index );
		}
	}
	$queue[] = array( 'settings', 0 );
	update_option(
		YAPD_IMPORT_STATE,
		array(
			'running' => true,
			'total'   => count( $queue ),
			'queue'   => $queue,
			'created' => 0,
			'skipped' => 0,
			'errors'  => array(),
		),
		false
	);
}

/** Processes queued entries until the time budget is used. */
function yapd_import_step(): array {
	$state = get_option( YAPD_IMPORT_STATE );
	if ( empty( $state['running'] ) ) {
		return is_array( $state ) ? $state : array();
	}

	$GLOBALS['yapd_importing'] = true; // No rebuild per entry (see yapd_trigger_build).
	wp_raise_memory_limit( 'admin' );
	$start = microtime( true );
	$seed  = yapd_import_seed();

	while ( $state['queue'] && microtime( true ) - $start < YAPD_IMPORT_TIME_BUDGET ) {
		list( $collection, $index ) = array_shift( $state['queue'] );
		try {
			$result = 'settings' === $collection
				? yapd_import_settings( $seed['settings'] ?? array() )
				: yapd_import_entry( $collection, $seed[ $collection ][ $index ] );
			++$state[ $result ];
		} catch ( Throwable $e ) {
			$title             = $seed[ $collection ][ $index ]['title'] ?? $collection;
			$state['errors'][] = "{$collection} / {$title}: " . $e->getMessage();
		}
		update_option( YAPD_IMPORT_STATE, $state, false );
	}

	unset( $GLOBALS['yapd_importing'] );
	if ( ! $state['queue'] ) {
		$state['running'] = false;
		update_option( YAPD_IMPORT_STATE, $state, false );
		delete_transient( 'yapd_build_pending' );
		yapd_trigger_build( "content import ({$state['created']} entries)" );
	}
	return $state;
}

add_action(
	'admin_menu',
	static function (): void {
		add_management_page( 'YAPD4Africa import', 'YAPD4Africa import', 'manage_options', 'yapd-import', 'yapd_render_import_page' );
	}
);

function yapd_render_import_page(): void {
	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}
	$page = admin_url( 'tools.php?page=yapd-import' );
	$seed = yapd_import_seed();

	// Start, then one batch per page load.
	$action = sanitize_key( wp_unslash( $_GET['yapd_import'] ?? '' ) ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended -- verified below.
	if ( $action ) {
		check_admin_referer( 'yapd_import' );
		if ( ! function_exists( 'update_field' ) ) {
			wp_die( esc_html__( 'Advanced Custom Fields must be active before importing.', 'yapd4africa-headless' ) );
		}
		if ( 'start' === $action ) {
			yapd_import_start();
		}
		$state = yapd_import_step();
	} else {
		$state = get_option( YAPD_IMPORT_STATE );
	}

	$next = wp_nonce_url( add_query_arg( 'yapd_import', 'continue', $page ), 'yapd_import' );
	echo '<div class="wrap"><h1>' . esc_html__( 'YAPD4Africa import', 'yapd4africa-headless' ) . '</h1>';

	if ( ! empty( $state['running'] ) ) {
		$done = $state['total'] - count( $state['queue'] );
		printf(
			'<meta http-equiv="refresh" content="1;url=%s"><p><strong>%s</strong> %d / %d</p><progress max="%d" value="%d" style="width:100%%;max-width:480px;height:20px"></progress><p class="description">%s</p></div>',
			esc_url( $next ),
			esc_html__( 'Importing…', 'yapd4africa-headless' ),
			(int) $done,
			(int) $state['total'],
			(int) $state['total'],
			(int) $done,
			esc_html__( 'Keep this page open. Images and PDFs are downloaded one by one; this takes a few minutes.', 'yapd4africa-headless' )
		);
		return;
	}

	if ( is_array( $state ) && isset( $state['total'] ) ) {
		printf(
			'<div class="notice notice-%s"><p>%s</p></div>',
			$state['errors'] ? 'warning' : 'success',
			esc_html(
				sprintf(
					/* translators: 1: created, 2: skipped, 3: errors */
					__( 'Import finished: %1$d created, %2$d already present, %3$d errors. The website is being rebuilt with this content.', 'yapd4africa-headless' ),
					$state['created'],
					$state['skipped'],
					count( $state['errors'] )
				)
			)
		);
		if ( $state['errors'] ) {
			echo '<ul style="list-style:disc;padding-left:20px">';
			foreach ( $state['errors'] as $error ) {
				echo '<li>' . esc_html( $error ) . '</li>';
			}
			echo '</ul><p>' . esc_html__( 'Run the import again to retry: entries already imported are skipped.', 'yapd4africa-headless' ) . '</p>';
		}
	}

	echo '<p>' . esc_html__( 'Copies the content currently shown on yapd4africa.org into WordPress, with images and PDFs, so the team can edit it here. Entries that already exist (same slug) are left untouched, and so are contact details and figures already entered in the settings.', 'yapd4africa-headless' ) . '</p>';
	echo '<table class="widefat striped" style="max-width:480px"><thead><tr><th>' . esc_html__( 'Content', 'yapd4africa-headless' ) . '</th><th>' . esc_html__( 'To import', 'yapd4africa-headless' ) . '</th><th>' . esc_html__( 'Already in WordPress', 'yapd4africa-headless' ) . '</th></tr></thead><tbody>';
	foreach ( YAPD_IMPORT_TYPES as $collection => $post_type ) {
		$items   = $seed[ $collection ] ?? array();
		$present = count( array_filter( $items, static fn( $item ) => yapd_import_find( $post_type, $item['slug'] ) ) );
		printf(
			'<tr><td>%s</td><td>%d</td><td>%d</td></tr>',
			esc_html( get_post_type_object( $post_type )->labels->name ?? $collection ),
			count( $items ) - $present,
			$present // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- integer.
		);
	}
	echo '</tbody></table>';

	if ( ! function_exists( 'update_field' ) ) {
		echo '<p style="color:#b32d2e">' . esc_html__( 'Activate Advanced Custom Fields first.', 'yapd4africa-headless' ) . '</p></div>';
		return;
	}
	printf(
		'<p><a class="button button-primary button-hero" href="%s">%s</a></p></div>',
		esc_url( wp_nonce_url( add_query_arg( 'yapd_import', 'start', $page ), 'yapd_import' ) ),
		esc_html__( 'Import the website content', 'yapd4africa-headless' )
	);
}
